    hero:{eyebrow:'BETA ACTIVA · REAL ESTATE COMERCIAL OFF-MARKET',title:'<span>Presenta con</span><br><em>rigor.</em><br><span class="promise-gap" aria-hidden="true"></span><span>Conecta con</span><br><em>criterio.</em>',lede:'Del documento disperso al teaser institucional, y del teaser a la contraparte adecuada: matching anónimo entre activos y mandatos de compra, con el tipo de mandato que declara cada parte.',primary:'Solicita demo <span>↗</span>',secondary:'Ver cómo funciona <span>→</span>',traceTitle:'Trazabilidad completa',traceBody:'Cada dato del teaser está vinculado a su fuente.',teaserTag:'TEASER INSTITUCIONAL · PREMIUM',teaserLoc:'Barcelona · España · Perfil anónimo',gla:'m² SBA',keys:'habitaciones',category:'categoría',teaserSource:'Trazable por origen · 1 / 3',provChip:'rent_roll_2026.xlsx · D8',provState:'verificado',radarTitle:'RADAR DE MANDATOS',radarLive:'3 matches nuevos',mandateMeta:'España · 50–150 M€ · identidad protegida',mandateLabel:'MANDATO DE COMPRA',mandateTitle:'Hotel urbano · core / core+'},
