function setText(selector, value, html = false) { const el = $(selector); if (el) html ? (el.innerHTML = value) : (el.textContent = value); }
function setAll(selector, values, html = false) { $$(selector).forEach((el, i) => { if (values[i] !== undefined) html ? (el.innerHTML = values[i]) : (el.textContent = values[i]); }); }
function localizeStaticUi() {
  const ui = STATIC_UI[currentLang];
  setText('.crumbs', ui.crumbs, true); setAll('.app-sidebar .side-item', ui.sidebar); setAll('.panel-tabs span', ui.tabs);
  setAll('.teaser-sheet .sheet-meta span', [ui.confidential, ui.teaserMeta], true); setText('.teaser-sheet h3', ui.teaserTitle, true); setText('.sheet-location', ui.location); setText('.sheet-image span', ui.image); setAll('.sheet-stats small', ui.sheetStats); setText('.sheet-footer span', ui.sheetFooter);
  setText('.mandate-card p', ui.mandate, true); setAll('.metric-grid small', ui.portfolioLabels); setAll('.metric-grid .metric-up,.metric-grid .metric-neutral', ui.portfolioStatus);
  setAll('.footer-links a', ui.footerLinks, true);
  localizeDemoStage();
}
